#include<cstdio>
long long n,m,high[1000000+10]; 
long long tmp,left,right;
int main()
{
	scanf("%lld%lld",&n,&m); 
	for(long long i=1;i<=n;i++){
		scanf("%lld",&high[i]);
		if(high[i]>right) right=high[i]; 
	}
	while(left<=right){
		int mid=(left+right)/2;

		tmp=0;
		for(int i=1;i<=n;i++) 
		    if(high[i]>mid) tmp+=high[i]-mid;
		if(tmp<m) right=mid-1;
		else left=mid+1;
	}
	printf("%lld",right); 
	return 0; 
}

#include<bits/stdc++.h>
using namespace std;
#define N 1000002
long long int n,m,sum;
long long int a[N];
int main()
{
	cin>>n>>m;
	for(long long int i=1;i<=n;i++)
	{
		cin>>a[i];
	}
	sort(a+1,a+n+1);
	a[n+1]=a[n];
	for(long long int i=n;i>=0;i--)
	{
		sum+=(n-i)*(a[i+1]-a[i]);
		if(sum<m)
		{
			continue;
		}
		long long int before=sum-(n-i)*(a[i+1]-a[i]);
		long long int cha=m-before;
		long long int ans=a[i+1]-(cha/(n-i));
		if(cha%(n-i)!=0)
		{
			ans--;
		}

		cout<<ans;
		break;
	}
	return 0;
}
